import json, glob, os

def load_firing_alerts(dirpath, ns='otel-demo'):
    res=[]
    for p in sorted(glob.glob(os.path.join(dirpath,'*.json'))):
        with open(p) as f:
            data=json.load(f)
        for a in data:
            if a.get('state')!='firing':
                continue
            if a['labels'].get('namespace')!=ns:
                continue
            res.append({
                'alertname': a['labels'].get('alertname'),
                'service': a['labels'].get('service_name'),
                'severity': a['labels'].get('severity'),
                'summary': a['annotations'].get('summary'),
                'description': a['annotations'].get('description'),
                'activeAt': a.get('activeAt')
            })
    return res
alerts=load_firing_alerts('alerts')
for a in alerts:
    print(a)
